    22 | pub fn encode(msg: &Msg) -> String {
    23 |     match msg {
    24 |         Msg::Ping => "ping".into(),
    25 |         Msg::Hello(payload) => format!("v:2|hello|{}", payload),
    26 |         Msg::Heartbeat(sequence) => format!("v:2|heartbeat|{}", sequence),
    27 |     }
    28 | }
    29 | 
    30 | pub fn ping_roundtrip() -> Result<Msg, String> {
    31 |     decode(&encode(&Msg::Ping))
    32 | }
